রসায়ন প্রথম অধ্যায়

\section{চতুর্থ অধ্যায়: রাসায়নিক পরিবর্তন}

\subsection{রাসায়নিক বিক্রিয়া ও ত্রিন কেমিস্ট্রি}

\begin{enumerate}
    \item $2SO_2(g) + O_2(g) \leftrightarrow 2SO_3(g) + 44.8 kcal ev$, $(4.184 \times 44.8 kcal)$; এ বিক্রিয়াটি আপমারা বাঁকলে কীক্রান্ত পরিবর্তন করে?
    \begin{enumerate}
        \item SO_3 এর উৎপাদন হয়
        \item বিক্রিয়াটি সমৃদ্ধী হয়
        \item তরল SO_3 উৎপাদন হয়
        \item Q_2 এর পরিমাণ পায়
    \end{enumerate}
    \item কোনটি সামান্যবাহু শর্ত?
    \begin{enumerate}
        \item একক্ষেত্রিত
        \item উদ্বোধিত
        \item গতিশীল
        \item প্রভাবকের উপর নির্ভরশীল
    \end{enumerate}
    \item আজ্ঞাক্রিতভাবে রাসায়নিক ধারা ফুটুক সৃষ্টি করার সুযোগের ফুলনীতি কর্মটি?
    \begin{enumerate}
        \item 10
        \item 12
        \item 18
        \item 15
    \end{enumerate}
    \item ত্রিন কেমিস্ট্রির 12টি নীতির মধ্যে নিচের কোনটি সত্যিক নয়?
    \begin{enumerate}
        \item বর্ধ পদার্থ রোধকরণ
        \item সর্বোচ্চ এটি ইকোনোমিক
        \item হ্রাস দেবা
        \item প্রভাবকের অপরিবর্ত
    \end{enumerate}
    \item CH_3CH_2Br + NaOH(aq) $\rightarrow$ CH_3CH_2OH + NaBr বিক্রিয়াটির এমটি ইকুইমিক কত?
    \begin{enumerate}
        \item 29.11%
        \item 30.87%
        \item 36.12%
        \item 39.12%
    \end{enumerate}
    \item X + Y $\longrightarrow$ M + N (বক্তা)
    \begin{enumerate}
        \item 78g 98g
        \item 84g 92g
    \end{enumerate}
    \item উত্তরের বিক্রিয়া এমটি ইকুইমিক কত?
    \begin{enumerate}
        \item 47.72%
        \item 52.27%
        \item 85.71%
        \item 100%
    \end{enumerate}
    \item ত্রিন কেমিস্ট্রি কোনটি?
    \begin{enumerate}
        \item কৃত্রিম CO_2
        \item CO_2(g)
        \item 31.1°C এর নিচের তাপমাত্রা CO_2
        \item 72.8°C তাপমাত্রা CO_2
    \end{enumerate}
    \item প্রাথমিক রাবার প্রজননের সম্পূর্ণ ক্ষতি সাধিত হয়-কারণ রাবারের আছে?
    \begin{enumerate}
        \item [BUET '13-14']
        \item C-C বন্ধন
        \item C=C বন্ধন
        \item C=O বন্ধন
    \end{enumerate}
    \item সমুদ্রের সীমিতমাত্রা কোনটি?
    \begin{enumerate}
        \item ফ্রিক্টিকর রাসায়নিক সংশ্লেষ
        \item বর্জ্য পদার্থ প্রতিরোধ
        \item মাধ্যমিক গৌণ পদার্থের রূপ্তি
        \item নৃত্যমূল রিপার দ্রাবক ব্যবহার
    \end{enumerate}
    \item ত্রিন চাপে এনালাজি পরিবর্তন এক অভিজ্ঞরী শক্তির পরিবর্তনের সংশ্লেষ কোনটি?
    \begin{enumerate}
        \item H = E + PV
        \item \Delta H = \Delta E + P\Delta V
        \item \Delta H = \Delta E - V\Delta P
    \end{enumerate}
    \item ত্রিন কেমিস্ট্রির সমাধিক শব্দ নয় কোনটি?
    \begin{enumerate}
        \item Clean Chemistry
        \item Chemical Chemistry
        \item Benign Chemistry
        \item Sustainable Chemistry
    \end{enumerate}
    \item ত্রিন কেমিস্ট্রির ক্ষেত্রে নিচের কোনটি সত্য নয়?
    \begin{enumerate}
        \item সুপার ক্রিটিক্যাল CO_2 ব্যবহার হয়
        \item 1991 সালে এই শিক্ষাটি প্রথম ব্যবহার হয়
        \item এটি বিনাইন কেমিস্ট্রি নামে পরিচিত
        \item এর 11টি ফুল মন্ত্র আছে
    \end{enumerate}
\end{enumerate}

\section{বিক্রিয়ার হার, দিক ও গতিসূত্র}

\begin{enumerate}
    \item 20 mL 1.5 M NaOH দ্রব্য মিশ্রিত করলে মিশ্রণের মনমাতা কত?
    \begin{enumerate}
        \item 1.5 M
        \item 1.65 M
        \item 1.71 M
        \item 1.78 M
    \end{enumerate}
    \item একটি দ্রব্যে হাইড্রোজেন আয়নের মোলার মনমাতা 1 \times 10^{-9} হলে, হাইড্রোক্লাইড আয়নের মোলার মনমাতা কত হবে?
    \begin{enumerate}
        \item 1 \times 10^{-3}
        \item 1 \times 10^{-4}
        \item 1 \times 10^{-5}
        \item 1 \times 10^{-6}
    \end{enumerate}
    \item কোন দিনামক বার বিক্রিয়ার সাম্প্রতিক ও বিক্রিয়ার হার প্রক্রিয়া?
    \begin{enumerate}
        \item প্রতিবার
        \item তাপমাত্রা
        \item চাপমাত্রা
        \item সব কয়টি
    \end{enumerate}
    \item বিক্রিয়ার হারের একটি নিচের কোনটি সত্যিক নয়?
    \begin{enumerate}
        \item বিক্রিয়ার বেগ মনমাতা সূচিত
        \item তাপমাত্রা সূচিত

রাসায়নিক পরিবর্তন

\section{বাকার দ্রব্য ও pH এর প্রযোগ}

\subsection{339. H₂SO₄ এর কন্ট্রোলটে ক্ষার কোনটি? [MCAT: 17-18]}

\begin{tabular}{|c|c|}
\hline
ক. SO₃²⁻ & খ. H₃O⁺ \\
গ. HSO₄⁻ & ঘ. H₂SO₃ \\
\hline
\end{tabular}

\subsection{340. মানবদেহে কোন বাকারটি pH নির্ধারণ করে? [MCAT: 20-21]}

\begin{tabular}{|c|c|}
\hline
ক. CH₃COOH+HCO₃⁻ & খ. H₂CO₃ + NaHCO₃ \\
গ. NH₄OH + NH₄Cl & ঘ. CH₃COOH + CH₃COONa \\
\hline
\end{tabular}

\subsection{341. মানবের রক্তের pH রেজ কতটি? [ব. সে. ২০১৮]}

\begin{tabular}{|c|c|}
\hline
ক. 1.0 – 2.0 & খ. 4.8 – 7.5 \\
গ. 6.4 – 6.9 & ঘ. 7.35 – 7.45 \\
\hline
\end{tabular}

\subsection{342. মানবের রক্তের যাবতীয় pH রেজ? [ব. সে. ১৬; সি. সে. ১৬; বি. সে. ১৬]}

\begin{tabular}{|c|c|}
\hline
ক. 9.4 & খ. 8.3 \\
গ. 7.4 & ঘ. 6.4 \\
\hline
\end{tabular}

\subsection{343. মানবের রক্তের যাবতীয় pH 7.45 এর বেশি হলে, মোটরিং নাম কী? [ব. সে. ১৮]}

\begin{tabular}{|c|c|}
\hline
ক. ইন্টারনেসিস & খ. আসিডেসিস \\
গ. আলকোলেসিস & ঘ. আসিনেকেসিস \\
\hline
\end{tabular}

\subsection{348. জীবতাত্ত্বিক (Biological) pH রেজ কোনটি? [ব. সে. ১৮]}

\begin{tabular}{|c|c|}
\hline
ক. 6-9 & খ. 6.9-7.1 \\
গ. 6.4-7.9 & ঘ. 6.9-7.4 \\
\hline
\end{tabular}

\subsection{345. মানবের চোষের পানির pH কত? [ব. সে. ১৮]}

\begin{tabular}{|c|c|}
\hline
ক. 7.4 & খ. 4.8-7.5 \\
গ. 1.4-2.0 & ঘ. 6.6-6.9 \\
\hline
\end{tabular}

\subsection{346. পাকছুরীর পাচক রক্তে pH 4.74 হলে H⁺ অ্যানায়ের ঘনমাত্রা কত? [ব. সে. ১৮]}

\begin{tabular}{|c|c|}
\hline
ক. 1 M & খ. 0.398 M \\
গ. 0.000018 M & ঘ. বিক্রিয়া \\
\hline
\end{tabular}

\subsection{347. অত্রীয় মাটির pH বৃদ্ধির জন্য নিচের কোন রাসায়নিক পদার্থ ব্যবহার করে থাকে? [ব. সে. ১৮]}

\begin{tabular}{|c|c|}
\hline
ক. ইন্টার্যাসার & খ. এম ও পি সার \\
গ. ডালোমাইট, চন & ঘ. ত্যাগ সার \\
\hline
\end{tabular}

\subsection{348. মাটির pH মান কমানোর জন্য কোনটি ব্যবহৃত হয়? [ব. সে. ২০১৮]}

\begin{tabular}{|c|c|}
\hline
ক. CaCO₃,MgCO₃ & খ. (NH₄)₂CO₃ \\
গ. (NH₄)₂HPO₄ & ঘ. CaO \\
\hline
\end{tabular}

\subsection{349. নিচের কোনটি দিয়ে অত্রীয় বাকার দ্রব্য তৈরি করে? [ব. সে. ২০১৫]}

\begin{tabular}{|c|c|}
\hline
ক. CH₃COOH ও NaOH & খ. CH₃COOH ও NH₄OH \\
গ. NH₄OH ও HCl & ঘ. NaOH ও HCl \\
\hline
\end{tabular}

\subsection{350. নিচের কোনটি দিয়ে অত্রীয় বাকার দ্রব্য তৈরি করে? [MCAT: 21-22]}

\begin{tabular}{|c|c|}
\hline
ক. CH₃COOH ও CH₃COONa & খ. CH₃COOH/CH₃COOH \\
গ. Na₂SO₄ ও H₂SO₄ & ঘ. H₂CO₃/NaHCO₃ \\
\hline
\end{tabular}

\subsection{351. মানব রক্তে কোন বাকার দ্রব্য বিন্যামানগ্রাহ্য? [ব. সে. ২০১৮]}

\begin{tabular}{|c|c|}
\hline
ক. NaHCO₃ + H₂CO₃ & খ. CH₃COONa + CH₃COOH \\
গ. Na₂HPO₄ + H₂PO₄ & ঘ. NH₄Cl + NH₄OH \\
\hline
\end{tabular}

\subsection{352. অত্রীয় বাকার দ্রব্যের pH নির্ধারণের সমীকরণ হলো কোনটি? [ব. সে. ১৮]}

\begin{tabular}{|c|c|}
\hline
ক. pH = pKa+log [অ্যালো] & খ. pH = pKa+log [লবণ] \\
গ. pH = pKa-log [অ্যালো] & ঘ. pH = pKa-log [লবণ] \\
\hline
\end{tabular}

\subsection{353. নিচের কোন যৌগকে কোন pH 7.4 যুক্ত দ্রব্য গোল করলে এর pH মান কমবে? [MCAT: 17-18]}

\begin{tabular}{|c|c|}
\hline
ক. C₂H₅OH & খ. C₃H₆O \\
গ. CH₃COOH & ঘ. C₆H₆ \\
\hline
\end{tabular}

\subsection{354. দুর্বল এসিড HX ও NaOH এর দ্বিকর্ম, HX(aq) + NaOH(aq) → NaX(aq) + H₂O(l); একেকে NaX এর জলীয় দ্রব্য সাধারণ pH কত হবে কোনটি? [ব. সে. ১৬]}

\begin{tabular}{|c|c|}
\hline
ক. 5.5 & খ. 7.0 \\
গ. 8.5 & ঘ. 3.0 \\
\hline
\end{tabular}

\subsection{355. রক্তের বাইকার্বনেট বাকারের pH ম
